"""Training examples for the skills the bot model keeps failing, generated by code so every answer is computed, never guessed.

Skills (exact JSON answers): was it sent / is it known / completion percent / which tool call / reminder fields / counting without double-counting.
Plus memory skills (scripts/memory-skills.py) and your own examples (custom-training.js). Plus: honest answers when data is missing or supplied, and plain general questions so the model does not forget how to chat.

Hold-out rule: nothing here may equal a prompt of the regression gate (activation-gate.py). The gate uses its own wording; this file uses
other wordings of the same skills, so a pass means the skill transferred, not that the test was memorised.
"""
import random, json, importlib.util, pathlib

_g = importlib.util.spec_from_file_location('gate', pathlib.Path(__file__).with_name('activation-gate.py')); gate = importlib.util.module_from_spec(_g); _g.loader.exec_module(gate)
GATE_PROMPTS = {p for _, p, _ in gate.CASES} | {p for _, p, _ in gate.EXTRA} | {p for p, _ in gate.GENERAL}
_f = importlib.util.spec_from_file_location('freedata', pathlib.Path(__file__).with_name('free-data.py')); freedata = importlib.util.module_from_spec(_f); _f.loader.exec_module(freedata)
_p = importlib.util.spec_from_file_location('packskills', pathlib.Path(__file__).with_name('pack-skills.py')); packskills = importlib.util.module_from_spec(_p); _p.loader.exec_module(packskills)
_m = importlib.util.spec_from_file_location('memskills', pathlib.Path(__file__).with_name('memory-skills.py')); memskills = importlib.util.module_from_spec(_m); _m.loader.exec_module(memskills)
J = lambda o: json.dumps(o, ensure_ascii=False, separators=(',', ':'))
NAMES = ['Ana', 'Ben', 'Carla', 'Dante', 'Elena', 'Felix', 'Gina', 'Hugo', 'Iris', 'Jun', 'Karla', 'Luis']
CHANNELS = ['Teams', 'email', 'Slack', 'Jira comment', 'WhatsApp', 'Outlook']


def sent(r):
    ch, who = r.choice(CHANNELS), r.choice(NAMES)
    t = r.choice([
        ('Tool result: {ch} draft prepared for {w}, not sent. Return JSON only: {{"sent": boolean}}.', False),
        ('Tool result: {ch} message delivered to {w}. Return JSON only: {{"sent": boolean}}.', True),
        ('The assistant saved a {ch} draft for {w} and is waiting for approval. Return JSON only: {{"sent": boolean}}.', False),
        ('Log: {ch} send action completed for {w}. Return JSON only: {{"sent": boolean}}.', True),
        ('Status: {ch} reply to {w} is only a draft, nothing went out. Answer in JSON only: {{"sent": boolean}}.', False),
        ('Result: the {ch} note to {w} was posted successfully. Reply with JSON only: {{"sent": boolean}}.', True),
    ])
    return t[0].format(ch=ch, w=who), J({'sent': t[1]})


def known(r):
    src = r.choice(['Outlook', 'Google', 'team', 'personal', 'Ascendion', 'work', 'client'])
    t = r.choice([
        ('The {s} calendar is not signed in. Is the number of {s} meetings known? Return JSON only: {{"known": boolean}}.', False),
        ('The {s} calendar is unavailable right now. Do we know how many {s} meetings there are? Return JSON only: {{"known": boolean}}.', False),
        ('The {s} calendar returned an error. Is the number of {s} meetings known? JSON only: {{"known": boolean}}.', False),
        ('The {s} calendar is connected and returned {n} meetings for today. Is the number of {s} meetings known? Return JSON only: {{"known": boolean}}.', True),
        ('The {s} calendar was read successfully: {n} events. Is the number of {s} events known? JSON only: {{"known": boolean}}.', True),
    ])
    return t[0].format(s=src, n=r.randint(0, 9)), J({'known': t[1]})


def percent(r):
    total = r.choice([4, 5, 8, 10, 16, 20, 25, 30, 40, 40, 40, 50, 60, 80, 100, 200, 250]); n = r.choice([k for k in range(1, total) if (k * 100) % total == 0] or [total // 2])
    t = r.choice([
        '{n} of {t} tickets are done. Return JSON only with numeric completion_percent.',
        'Sprint status: {n}/{t} stories finished. Return JSON only with numeric completion_percent.',
        'We closed {n} out of {t} tasks. Return JSON only with a whole-number completion_percent.',
        'Progress report: {n} done, {r} remaining, {t} in total. Return JSON only with numeric completion_percent.',
    ])
    return t.format(n=n, t=total, r=total - n), J({'completion_percent': n * 100 // total})


TOOLS = [('find_files', 'name', ['report.pdf', 'budget.xlsx', 'notes.md', 'invoice-2026.pdf', 'roadmap.pptx', 'todo.txt', 'logo.png', 'data.csv']),
         ('open_app', 'app', ['Safari', 'Notes', 'Calendar', 'Terminal', 'Slack']), ('search_web', 'query', ['llama.cpp release', 'mlx lora guide', 'swift concurrency']),
         ('read_file', 'path', ['README.md', 'package.json', 'src/index.ts'])]


def tool_call(r):
    tool, arg, vals = r.choice(TOOLS); v = r.choice(vals)
    verb = {'find_files': 'Find', 'open_app': 'Open', 'search_web': 'Search for', 'read_file': 'Read'}[tool]
    t = r.choice(['{v} {x}. The only tool is {tool} with required string argument {a} and no other arguments. Return JSON only with name and arguments.',
                  'Task: {v} {x}. Available tool: {tool}(required string {a}, nothing else allowed). Answer with JSON only containing name and arguments.',
                  '{v} {x} using {tool}. It takes exactly one argument, {a}, a string. Return JSON only with name and arguments.'])
    return t.format(v=verb, x=v, tool=tool, a=arg), J({'name': tool, 'arguments': {arg: v}})


FREQ = [('weekdays', 'weekdays'), ('every weekday', 'weekdays'), ('daily', 'daily'), ('every day', 'daily'), ('weekly', 'weekly'), ('monthly', 'monthly')]
ZONES = ['Asia/Manila', 'Asia/Tokyo', 'Europe/London', 'America/New_York', 'Australia/Sydney', 'Asia/Singapore']
TITLES = ['Team standup', 'Submit timesheet', 'Backup check', 'Review pull requests', 'Water the plants', 'Weekly report', 'Call mom', 'Sprint planning',
          # the title is not the frequency: "Daily review" can repeat on weekdays, "Weekly sync" can repeat daily
          'Daily review', 'Daily standup prep', 'Weekly sync notes', 'Monthly report draft', 'Daily Work Review', 'Weekly Setup', 'Daily timesheet', 'Daily Work Planning', 'Daily Setup Check', 'Daily Work Wrap-up', 'Daily Desk Setup', 'Daily Work Log', 'Work Setup']


def reminder(r):
    fx, fv = r.choice(FREQ); h, m = r.choice([6, 7, 8, 9, 10, 13, 15, 17, 18, 21]), r.choice([0, 5, 15, 30, 45]); z, title = r.choice(ZONES), r.choice(TITLES[8:] if r.random() < 0.6 else TITLES)
    if r.random() < 0.7:  # most of the time the title names a different frequency than the schedule ("Daily Work Setup" on weekdays): the schedule wins, never the title
        word = r.choice(['Daily', 'Weekly', 'Monthly']); title = r.choice([f'{word} Work Setup', f'{word} standup', f'{word} review', f'{word} report', f'{word} check-in', f'{word} planning'])
        same = {'Daily': {'daily'}, 'Weekly': {'weekly'}, 'Monthly': {'monthly'}}[word]; opts = [f for f in FREQ if f[1] not in same]; fx, fv = r.choice(opts)
    if r.random() < 0.35:
        ap = 'AM' if h < 12 else 'PM'; h12 = h % 12 or 12; when = f'{h12}:{m:02d} {ap}'
    else:
        when = f'{h:02d}:{m:02d}'
    t = r.choice(['Saved reminder: {f} {w} {z}, {ti}. Return JSON only with time in HH:MM, timezone, and frequency.',
                  'Reminder saved. Repeats {f} at {w} ({z}). Title: {ti}. Return JSON only with time in HH:MM, timezone, and frequency.',
                  'Schedule entry: {ti}, {f}, {w} {z}. Return JSON only with time in HH:MM (24-hour), timezone, and frequency.'])
    return t.format(f=fx, w=when, z=z, ti=title), J({'time': f'{h:02d}:{m:02d}', 'timezone': z, 'frequency': fv})


def dedup(r):
    pre = r.choice(['A', 'WEB', 'MB', 'API', 'T', 'B']); mode = r.random()
    if mode < 0.55:  # the shape that goes wrong: one Done ticket listed twice must still count once
        ids = r.sample(range(1, 10), 3); sts = ['Done', 'Blocked', 'Open']; r.shuffle(sts); status = dict(zip(ids, sts)); dup = next(i for i in ids if status[i] == 'Done' or r.random() < 0.15)
        seq = list(ids); seq.insert(seq.index(dup) + (0 if r.random() < 0.7 else r.randint(0, 2)), dup)
    else:
        ids = r.sample(range(1, 30), r.randint(3, 6)); status = {i: r.choice(['Done', 'Open', 'Blocked', 'Done']) for i in ids}; seq = list(ids)
        for _ in range(r.randint(1, 3)): seq.append(r.choice(ids))
        r.shuffle(seq)
    listing = ', '.join(f'{pre}-{i} {status[i]}' for i in seq)
    out = {'unique_count': len(ids), 'done_count': sum(s == 'Done' for s in status.values()), 'blocked_count': sum(s == 'Blocked' for s in status.values())}
    t = r.choice(['Tickets: {l}. Return JSON only with numeric unique_count, done_count and blocked_count.', 'Ticket list (duplicates are repeated lines of the same ticket): {l}. Return JSON only with numeric unique_count, done_count and blocked_count.'])
    return t.format(l=listing), J(out)


def honesty(r):
    total = r.randint(6, 40); blocked = r.randint(0, total // 2); overdue = r.randint(0, total // 3)
    if r.random() < 0.5:
        q = r.choice(['How many Jira tickets are blocked? No Jira data was provided.', 'What is the team velocity this sprint? I have not given you any sprint data.', 'How many meetings do I have tomorrow? The calendar is not connected.', 'Which MRs are waiting for review? GitLab is not connected.'])
        a = {'How many Jira tickets': "I don't have that number: no Jira data was provided, so I won't guess.", 'What is the team velocity': "I can't tell you the velocity: no sprint data was provided, so I won't make up a number.",
             'How many meetings do': "I can't tell: the calendar is not connected, so I don't know how many meetings you have tomorrow.", 'Which MRs': "I can't see them: GitLab is not connected, so I can't list the merge requests waiting for review."}
        return q, next(v for k, v in a.items() if q.startswith(k))
    q = r.choice(['Jira data: {t} tickets, {b} blocked, {o} overdue. How many are blocked? Answer in one sentence.', 'From the board export: total {t}, blocked {b}, overdue {o}. How many tickets are overdue? Answer in one sentence.'])
    which = 'blocked' if 'How many are blocked' in q else 'overdue'; n = blocked if which == 'blocked' else overdue
    return q.format(t=total, b=blocked, o=overdue), f'{n} of the {total} tickets {"are" if n != 1 else "is"} {which}.'


