SKILLS = [sent] * 2 + [known] * 2 + [percent] * 7 + [tool_call] * 3 + [reminder] * 20 + [dedup] * 9 + [honesty] * 2  # the hard ones several times


def rehearsal():
    """Answers the unmodified base model already gave (checked or corrected), replayed during training so it keeps what it knows."""
    try: return json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/rehearsal.json').read_text())['examples']
    except Exception: return []


def nlu_examples():
    """The bot's real understanding prompt + checked answers (scripts/make-nlu-examples.js). Never contains a gate utterance."""
    try: return json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/nlu-examples.json').read_text())['examples']
    except Exception: return []


def chat_rehearsal():
    """Multi-turn conversations in the bot's real answer prompt, answered by the unmodified base model (scripts/make-chat-rehearsal.js)."""
    try: return json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/chat-rehearsal.json').read_text())['examples']
    except Exception: return []


import os, re
SECRET = re.compile(r"\b(password|passcode|api[ -]?key|secret|token|credit card|card number|cvv|ssn|private key)\b|\bsk-[a-z0-9]{6,}|\b\d{4}[ -]\d{4}[ -]\d{4}[ -]\d{4}\b", re.I)



WORD = re.compile(r"[a-z][a-z0-9_]{2,}")
STOP = {'the', 'and', 'for', 'with', 'that', 'this', 'what', 'your', 'you', 'are', 'how', 'can', 'from', 'into', 'give', 'write', 'show', 'please', 'one', 'only'}


def failed_checks(runs, catalog):
    """Full prompts of the pack checks failed in these runs' quality check (gguf-gate.json names are 'Pack: first 52 chars of the prompt')."""
    by = {}
    for p in catalog:
        for c in p.get('checks', []): by[p['name'] + ': ' + ' '.join(c['prompt'].split())[:52]] = (p['id'], c['prompt'])
    out = {}
    for r in runs:
        try: g = json.loads((custom_dir().parent / 'runs' / r / 'deployment' / 'gguf-gate.json').read_text())
        except Exception: continue
        for c in g.get('cases', []):
            if c.get('group') == 'pack' and not c.get('passed') and c.get('name') in by: out[c['name']] = by[c['name']]
    return list(out.values())


def mistake_rows(train, catalog, checks, k=8):
    """For every failed check: the k training rows (dict or [q, a]) most like it by shared words. Never the check prompt itself."""
    runs = [x for x in (os.environ.get('TULAI_MISTAKES_RUNS') or os.environ.get('TULAI_RESUME_RUN') or '').split(',') if x.strip()]
    fails = failed_checks(runs, catalog)
    if not fails: return []
    q = lambda it: ' || '.join(m['content'] for m in it['messages'] if m['role'] == 'user') if isinstance(it, dict) else it[0]
    bag = lambda t: {w for w in WORD.findall(t.lower()) if w not in STOP}
    cand = [(it, bag(q(it))) for it in train if ' '.join(q(it).lower().split()) not in checks]
    picked, seen = [], set()
    for _, prompt in fails:
        want = bag(prompt)
        best = sorted(((len(want & b) / (len(want | b) or 1), i) for i, (_, b) in enumerate(cand) if want & b), reverse=True)[:k]
        for sc, i in best:
            if sc > 0.05 and i not in seen: seen.add(i); picked.append(cand[i][0])
    print(f'Learning from previous mistakes: {len(fails)} failed checks -> {len(picked)} similar practice rows x3', flush=True)
    return picked

def custom_dir():
    base = os.environ.get('TULAI_DATA_DIR') or os.environ.get('GC_DATA_DIR') or str(pathlib.Path.home() / 'Library/Application Support/gateway-chat')
    return pathlib.Path(os.environ.get('TULAI_CUSTOM_DIR') or (pathlib.Path(base) / 'training' / 'custom'))


def custom_examples():
    """Your own examples (training/custom/*.jsonl|json): {"prompt","answer"[, "memory":[notes]]} or {"messages":[...]}. Checks ("check": true) are for the gate only.
    Secrets and malformed rows are skipped. Returns chat rows ({"messages": [...]})."""
    d = custom_dir(); rows = []
    if not d.is_dir(): return rows
    for f in sorted(d.glob('*.json*')):
        try:
            txt = f.read_text(encoding='utf-8')
            if f.suffix == '.jsonl':
                items = []
                for l in txt.splitlines():
                    try: items.append(json.loads(l))
                    except Exception: pass  # one bad line never drops the file
            else: items = (lambda j: j if isinstance(j, list) else j.get('examples', []))(json.loads(txt))
        except Exception: continue
        for e in items:
            try:
                if not isinstance(e, dict) or e.get('check'): continue
                memory = [str(m)[:240] for m in (e.get('memory') or []) if str(m).strip()][:8]
                if isinstance(e.get('messages'), list) and len(e['messages']) >= 2 and e['messages'][-1].get('role') == 'assistant':
                    msgs = [{'role': m['role'], 'content': str(m['content'])[:1500]} for m in e['messages'] if m.get('role') in ('system', 'user', 'assistant') and str(m.get('content', '')).strip()]
                    if msgs[0]['role'] != 'system': msgs.insert(0, {'role': 'system', 'content': memskills.system_prompt()})
                    if memory: msgs.insert(1, {'role': 'user', 'content': memskills.context(memory)})
                    text = ' '.join(m['content'] for m in msgs)
                    if SECRET.search(text): continue
                    rows.append({'messages': msgs}); continue
                p, a = str(e.get('prompt', '')).strip()[:1500], str(e.get('answer', '')).strip()[:1500]
                if len(p) < 3 or not a or SECRET.search(p + ' ' + a + ' ' + ' '.join(memory)): continue
                rows.append(memskills.row(None, memory, p, a))
            except Exception: continue
    return rows


def gate_prompt_texts(): return GATE_PROMPTS | memory_gate_texts()


def memory_gate_texts():
    # no silent fallback: if the gate questions cannot be read, training must stop rather than risk teaching the test
    return {c['text'].lower().strip() for c in json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/nlu-gate-cases.json').read_text()).get('memory', [])}


def build(seed=7, n_train=None, n_valid=24, n_test=24):
    """Returns {'origin', 'train', 'valid', 'test'} of [prompt, answer]; no prompt appears twice or equals a gate prompt."""
    n_train = n_train or 760 + 60 * len([x for x in os.environ.get('TULAI_PACKS', '').split(',') if x.strip()])  # each skill pack adds rows; the older skills get more rows too, so they are not drowned
    rng = random.Random(seed); seen = set(' '.join(p.lower().split()) for p in GATE_PROMPTS)
    out = {'origin': 'Generated skill examples (answers computed by code, including memory skills), replayed base-model answers, general questions and your own examples; gate prompts excluded.', 'train': [], 'valid': [], 'test': []}
    pool = [g for g in rehearsal() + GENERAL if ' '.join(g[0].lower().split()) not in seen]; rng.shuffle(pool)
    quota = {'train': 100, 'valid': 6, 'test': 6}; pi = 0; base_pool = []
    for split, n in (('train', n_train), ('valid', n_valid), ('test', n_test)):
        got = 0
        while got < quota[split] and pi < len(pool):
            p, a = pool[pi]; pi += 1; k = ' '.join(p.lower().split())
            if k in seen: continue
            seen.add(k); out[split].append([p, a]); got += 1
            if split == 'train': base_pool.append([p, a])
        tries = 0; i = 0
        while len(out[split]) < n and tries < n * 100:
            tries += 1; p, a = SKILLS[i % len(SKILLS)](rng); k = ' '.join(p.lower().split())
            if k in seen: continue
            seen.add(k); out[split].append([p, a]); i += 1
    npk = len([x for x in os.environ.get('TULAI_PACKS', '').split(',') if x.strip()]); rep = (2 + npk // 2) if npk else 1  # skill packs add thousands of exact-format rows: the everyday behaviors (commands, conversation, plain questions) are repeated so they are not drowned
    nlu = nlu_examples(); rng.shuffle(nlu); out['valid'] += nlu[:2]; out['test'] += nlu[2:4]; out['train'] += nlu[4:] * rep
    chat = chat_rehearsal(); rng.shuffle(chat); out['valid'] += chat[:2]; out['test'] += chat[2:4]; out['train'] += chat[4:] * rep
    out['train'] += base_pool * (rep - 1)
    mem = memskills.build(seed, 260, memory_gate_texts()); out['valid'] += mem[:3]; out['test'] += mem[3:6]; out['train'] += mem[6:]
    mine = custom_examples()
    if mine:  # your own examples: one in eight is held back to measure, the rest are repeated so a few examples are enough to be learned
        rng.shuffle(mine); hold = max(1, len(mine) // 8) if len(mine) >= 8 else 0; out['valid'] += mine[:hold]
        for _ in range(3): out['train'] += mine[hold:]
        out['custom'] = len(mine)
    out['memory'] = len(mem)
    taken = set(' '.join(x.lower().split()) for x in gate_prompt_texts())  # free data never repeats a question already used (the trainer rejects the same input twice)
    for sp in ('train', 'valid', 'test'):
        for it in out[sp]: taken.add(' '.join((' || '.join(m['content'] for m in it['messages'] if m['role'] == 'user') if isinstance(it, dict) else it[0]).lower().split()))
    free, fcounts = freedata.rows(seed, memskills.system_prompt(), taken)
    if free: out['valid'] += free[:3]; out['test'] += free[3:6]; out['train'] += free[6:]
    out['free'] = fcounts
    packs = [x for x in os.environ.get('TULAI_PACKS', '').split(',') if x.strip()]  # skill packs chosen with one click (skill-packs.js)
    if packs:
        for sp in ('train', 'valid', 'test'):
            for it in out[sp]: taken.add(' '.join((' || '.join(m['content'] for m in it['messages'] if m['role'] == 'user') if isinstance(it, dict) else it[0]).lower().split()))
        checks = {' '.join(c['prompt'].lower().split()) for p in packskills.catalog() for c in p.get('checks', [])}  # the held-out checks of every pack, selected or not
        try: packskills.BANNED |= set(json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/acceptance-prompts.json').read_text())['sha256'])  # the self-test questions: never trained, so the self-test stays independent
        except FileNotFoundError: pass
        prows, pcounts = packskills.rows(packs, seed, taken | checks, memskills.system_prompt(), memskills.row)
        k = max(2, len(prows) // 60); out['valid'] += prows[:k]; out['train'] += prows[k:]; out['packs'] = pcounts
        new = [x for x in os.environ.get('TULAI_NEW_PACKS', '').split(',') if x.strip() and x in packs]
        if new:  # continuing from a trained brain: a pack it does not know yet is practised 3 times as often, the known ones are reviewed once
            nrows, _ = packskills.rows(new, seed, taken | checks, memskills.system_prompt(), memskills.row); key = lambda it: ' '.join((' || '.join(m['content'] for m in it['messages'] if m['role'] == 'user') if isinstance(it, dict) else it[0]).lower().split())
            held = {key(it) for sp in ('valid', 'test') for it in out[sp]}  # generated on their own, so a few can repeat a validation question: those stay out of train
            out['train'] += [it for it in nrows if key(it) not in held] * 2
    if packs:  # learn from previous mistakes: the checks the last try(s) failed get 3x practice on the closest training rows (same skill, other question)
        extra = mistake_rows(out['train'], packskills.catalog(), checks)
        if extra: out['train'] += extra * 2; out['mistakes'] = len(extra)
    if packs:  # coding-agent practice (training-config/agent-episodes.json): use the tools on the real files instead of asking for the code
        try:
            eps = json.loads((pathlib.Path(__file__).resolve().parents[1] / 'training-config/agent-episodes.json').read_text())['episodes']; rng.shuffle(eps)
            # training learns only the LAST message of a row (--mask-prompt), so every step is its own row: "read the file", "edit it", "run the test", "report"
            steps = lambda e: [{'messages': e['messages'][:k + 1], 'tools': e['tools']} for k, m in enumerate(e['messages']) if m['role'] == 'assistant']
            out['valid'] += [r for e in eps[:2] for r in steps(e)]; out['train'] += [r for e in eps[2:] for r in steps(e)] * 4; out['agent'] = len(eps)
        except FileNotFoundError: pass
    if packs:  # learn from the company AI: Sonnet's saved tool steps from your Tulai Desktop chats (training/sonnet/*.json, private, made by scripts/sonnet-episodes.js)
        son = []
        for f in sorted((custom_dir().parent / 'sonnet').glob('*.json')) if (custom_dir().parent / 'sonnet').is_dir() else []:
            try: son += [e for e in json.loads(f.read_text())['episodes'] if len(json.dumps(e)) < 9000 and not SECRET.search(json.dumps(e))]
            except Exception: pass
        if son: out['train'] += [{'messages': e['messages'], 'tools': e['tools']} for e in son]; out['sonnet'] = len(son)  # once: twice pulled the coder away from short tasks (Coding AI 5-7/10 that round)
    for s in ('train', 'valid', 'test'): rng.shuffle(out[s])
    return out


